// seed: tests/seed.admin.spec.ts
// #e1e502 (עבר QA 21.10): «מכירה מיידית» на телефоне 390 — строка товара в 2 ряда внутри карточки: название + удаление,
// под ними количество (+/−) · цена · сумма; название и поле количества видны, горизонтальной прокрутки нет.
// «רישום המכירה» НЕ нажимается — продажа не регистрируется, склад не меняется.
import { test, expect, Page, Locator } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const ITEM = 'מצית קליפט';
const W = 390;

async function inViewport(l: Locator, what: string) {
  await expect(l, what).toBeVisible();
  const b = (await l.boundingBox())!;
  expect(b.x, `${what}: левый край ${b.x}`).toBeGreaterThanOrEqual(0);
  expect(b.x + b.width, `${what}: правый край ${b.x + b.width}`).toBeLessThanOrEqual(W);
  return b;
}

async function noHorizontalScroll(page: Page) {
  const r = await page.evaluate(() => {
    const doc = { sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth };
    const scrollers = [...document.querySelectorAll('main *')]
      .filter((e) => e.scrollWidth > e.clientWidth + 1 && ['auto', 'scroll'].includes(getComputedStyle(e).overflowX))
      .map((e) => `${e.tagName} ${e.scrollWidth}/${e.clientWidth}`);
    return { doc, scrollers };
  });
  expect(r.doc.sw, 'ширина страницы = ширине экрана').toBeLessThanOrEqual(r.doc.cw);
  expect(r.scrollers, 'нет блоков с горизонтальной прокруткой').toEqual([]);
}

test.describe('orders — מכירה מיידית בטלפון 390 (#e1e502)', () => {
  test('שורת פריט בשתי שורות: שם המוצר והכמות בתוך המסך, בלי גלילה לרוחב #e1e502 @iphone', async ({ page }) => {
    await page.setViewportSize({ width: W, height: 844 });
    await page.goto('/orders/walk-in');
    await expect(page.getByRole('heading', { level: 1, name: 'מכירה מיידית' })).toBeVisible({ timeout: 30_000 });
    const search = page.getByRole('combobox', { name: 'חיפוש מוצר להוספה למכירה' });
    await search.fill('קליפט');
    await expect(page.getByRole('listbox', { name: 'תוצאות חיפוש מוצרים' }).getByRole('option', { name: new RegExp(ITEM) })).toBeVisible({ timeout: 20_000 });
    await search.press('Enter');

    const qty = page.getByRole('textbox', { name: `כמות — ${ITEM}` });
    await expect(qty).toBeVisible({ timeout: 15_000 });
    const name = await inViewport(page.getByRole('heading', { level: 3, name: 'פריטי המכירה' }).locator('xpath=following::*').getByText(ITEM, { exact: true }).first(), 'название товара');
    const q = await inViewport(qty, 'поле количества');
    await inViewport(page.getByRole('button', { name: `הוספת יחידה — ${ITEM}` }), '«+»');
    await inViewport(page.getByRole('button', { name: `הפחתת יחידה — ${ITEM}` }), '«−»');
    await inViewport(page.getByRole('spinbutton', { name: `מחיר יחידה — ${ITEM}` }), 'цена');
    await inViewport(page.getByRole('button', { name: `הסרת ${ITEM}` }), 'удаление');
    // два ряда: количество — ниже названия
    expect(q.y, 'количество во втором ряду, под названием').toBeGreaterThanOrEqual(name.y + name.height - 1);
    await noHorizontalScroll(page);

    // «+» работает, сумма строки и итог пересчитываются; раскладка не ломается
    await page.getByRole('button', { name: `הוספת יחידה — ${ITEM}` }).click();
    await expect(qty).toHaveValue('2');
    await expect(page.getByText('סה"כ לתשלום').locator('..')).toContainText('₪10.00');
    await noHorizontalScroll(page);
    await page.getByRole('button', { name: 'חזרה להזמנות' }).click(); // продажу не регистрируем
    await expect(page).toHaveURL(/\/orders$/);
  });
});
